// ---------------------------------------------------------------------------
// Act II — the Noon (docs/specs/GATE_ARC.md §17, §19, §20; docs/CAMPAIGN.md "Act II")
// ---------------------------------------------------------------------------

const round2 = (v) => Math.round(v * 100) / 100;

/**
 * Each chapter's mean hero-rework HP pass over its five Act I stages (1.69 / 1.77 / 1.4 / 2.15 / 1.92 / 1.77 / 2.19 /
 * 1.25). Act II of chapter c multiplies its rung by it: the pass encodes how much the free heroes help in that
 * chapter's mechanics, so raw hpScale is not comparable across chapters.
 */
export const CHAPTER_HP_PASS_MEAN = Object.freeze(Object.fromEntries(CHAPTERS.map((ch) => [ch.id,
  round2(ch.stages.reduce((a, id) => a + HERO_HP_PASS[id], 0) / ch.stages.length)])));

/** Chapter 8's Act II waves (there is no chapter 9 row to copy). */
const LAST_ACT2_WAVES = Object.freeze([30, 30, 31, 31, 32]);
/** Act II pays half medal gems: 10 / 20 / 30 / 50 (110 per stage instead of 220). */
export const ACT2_MEDAL_GEM_MUL = 0.5;

const ACT1_BY_ID = new Map(CAMPAIGN.map((s) => [s.id, s]));

/**
 * The plan of all 40 Act II stages ('c-6' … 'c-10'), computed from the Act I ramp, never typed in. For Act II stage k
 * of chapter c (k 1…5, id `c-(5+k)`, rung index i = 5c + k − 1, i.e. the plan's rungs 5…44 past 1-1):
 *   hpScale      hpScaleAt(i) × CHAPTER_HP_PASS_MEAN[c] (two decimals); hpPass = that mean (co-op freeplay divides it out)
 *   cashScale    cashScaleFor(hpScaleAt(i)); startCash startCashAt(i) capped at 900 (pre-pass, as Act I computes them)
 *   waves, tier  chapter c+1's Act I stage k (chapter 8: waves 30/30/31/31/32, tier expert)
 *   drops        campaignDrops(min(c+1, 8)) (chapter c+1's table); first clear campaignFirstClear(c, k === 5): x-10
 *                pays like x-5 (100 + 20c gems and a recruit ticket)
 *   requires     x-6: 'c-5' and '(c-1)-10' (1-6: '1-5' only); x-7 … x-10: the Act II stage before
 *   medalGemMul  0.5; modeChapter min(8, c+1) (Ironclad's armor row)
 * Starting values for the first balance run (the PROPOSED table of the Gate Arc tech notes, §5.2), pinned by
 * tests/data/act2Plan.test.js.
 * @type {ReadonlyArray<Readonly<{ id: string, chapter: number, k: number, n: number, waves: number, hpScale: number,
 *   hpPass: number, cashScale: number, startCash: number, tier: string, requires: string|ReadonlyArray<string>,
 *   dropChapter: number, modeChapter: number, medalGemMul: number, finale: boolean }>>}
 */
export const ACT2_PLAN = Object.freeze(CHAPTERS.flatMap((ch) => [1, 2, 3, 4, 5].map((k) => {
  const c = ch.id;
  const i = 5 * c + k - 1;
  const rung = hpScaleAt(i);
  const mean = CHAPTER_HP_PASS_MEAN[c];
  const next = ACT1_BY_ID.get(`${c + 1}-${k}`) || null;
  return Object.freeze({
    id: `${c}-${5 + k}`,
    chapter: c,
    k,
    n: 5 + k,
    waves: next ? next.waves : LAST_ACT2_WAVES[k - 1],
    hpScale: round2(rung * mean),
    hpPass: mean,
    cashScale: cashScaleFor(rung),
    startCash: Math.min(900, startCashAt(i)),
    tier: next ? next.tier : 'expert',
    requires: k > 1 ? `${c}-${4 + k}` : c === 1 ? '1-5' : Object.freeze([`${c}-5`, `${c - 1}-10`]),
    dropChapter: Math.min(c + 1, CHAPTERS.length),
    modeChapter: Math.min(c + 1, CHAPTERS.length),
    medalGemMul: ACT2_MEDAL_GEM_MUL,
    finale: k === 5,
  });
})));

export const ACT2_PLAN_MAP = Object.freeze(Object.fromEntries(ACT2_PLAN.map((r) => [r.id, r])));

/** StageDef fields an Act II stage takes from ACT2_PLAN only (act2Stage refuses them in its parameters). */
const ACT2_PLANNED = ['chapter', 'act', 'finale', 'waves', 'hpScale', 'hpPass', 'cashScale', 'startCash', 'requires', 'tier',
  'medalGemMul', 'modeChapter', 'drops', 'firstClear'];

/**
 * Builds an Act II ("the Noon") campaign StageDef: the authored parts come from `o` (name, map, desc, pool, budget,
 * fixed, spacing, groups, fam, crown, dice, introduces, recommended, unlocks, scenery), the numbers, requires, tier,
 * drops and first-clear rewards from ACT2_PLAN. Exported so tests can build fixture stages; only CAMPAIGN_ACT2
 * registers a stage.
 * @param {object} o stage parameters (o.id = 'c-6' … 'c-10')
 * @returns {object} StageDef
 */
export function act2Stage(o) {
  const plan = ACT2_PLAN_MAP[o?.id];
  if (!plan) throw new Error(`act2Stage: ${o?.id} is not an Act II stage id`);
  for (const k of ACT2_PLANNED) if (k in o) throw new Error(`act2Stage ${o.id}: '${k}' comes from ACT2_PLAN`);
  return {
    id: o.id,
    kind: 'campaign',
    chapter: plan.chapter,
    act: 2,
    finale: plan.finale,
    name: o.name,
    mapId: o.mapId,
    desc: o.desc,
    waves: plan.waves,
    waveGen: {
      pool: o.pool,
      budget: { start: o.budget[0], growth: growthFor(o.budget[0], o.budget[1], plan.waves) },
      spacing: o.spacing ?? 0.8,
      groups: o.groups ?? 3,
      fixed: o.fixed || [],
      // the lane schedule (Gate Arc: a level crossing closes a lane on some waves; src/sim/waves.js openLanes)
      ...(o.laneCycle ? { laneCycle: o.laneCycle } : {}),
    },
    hpScale: plan.hpScale,
    hpPass: plan.hpPass,
    cashScale: plan.cashScale,
    startCash: plan.startCash,
    lives: 100,
    introduces: o.introduces || [],
    recommended: o.recommended || [],
    unlocks: o.unlocks ? { units: o.unlocks } : {},
    requires: Array.isArray(plan.requires) ? [...plan.requires] : plan.requires,
    drops: campaignDrops(plan.dropChapter, o.fam, { dice: o.dice ?? (plan.dropChapter >= 3 ? 0.04 : 0), crown: o.crown || null }),
    firstClear: campaignFirstClear(plan.chapter, plan.finale),
    medalGemMul: plan.medalGemMul,
    modeChapter: plan.modeChapter,
    scenery: o.scenery,
    ...(o.look ? { look: o.look } : {}),
    tier: plan.tier,
    rule: stageRule(o.id),
  };
}

