/** Material drops for one family at a bounty tier. */
function arenaMaterial(family, tier, perFamily) {
  if (tier === 1) {
    return [D(mat(family, 'common'), perFamily, 2, 5), D(mat(family, 'rare'), perFamily * 0.35, 1, 2), D(mat(family, 'superRare'), 0.05, 1, 1, 'hard')];
  }
  if (tier === 2) {
    return [D(mat(family, 'rare'), perFamily, 2, 4), D(mat(family, 'superRare'), perFamily * 0.35, 1, 2), D(mat(family, 'mythic'), 0.03, 1, 1, 'hard')];
  }
  return [D(mat(family, 'superRare'), perFamily, 2, 3), D(mat(family, 'mythic'), perFamily * 0.25, 1, 1), D(mat(family, 'legendary'), 0.02, 1, 1, 'nightmare')];
}

