export const STAGES = [...CAMPAIGN, ...ACT2_SORTED, ...BOUNTY, ...BOSSES, CHALLENGE];

export const STAGE_MAP = Object.fromEntries(STAGES.map((s) => [s.id, s]));

/**
 * Look up a stage definition.
 * @param {string} id stage id, e.g. '1-1', 'res-books-2', 'boss-lych', 'challenge'
 * @returns {object} StageDef
 * @throws {Error} when the id is unknown
 */
export function getStage(id) {
  const s = STAGE_MAP[id];
  if (!s) throw new Error(`Unknown stage: ${id}`);
  return s;
}

/**
 * @returns {object[]} the campaign stages in CAMPAIGN_IDS order: the 40 of Act I (1-1 … 8-5), then every registered
 * Act II stage by (chapter, n). Filter on `act` for one act.
 */
export function campaignStages() {
  return [...CAMPAIGN, ...ACT2_SORTED];
}

/**
 * @param {'campaign'|'resource'|'boss'|'challenge'} kind
 * @returns {object[]} stages of that kind in display order
 */
export function stagesOfKind(kind) {
  return STAGES.filter((s) => s.kind === kind);
}

/**
 * Bounty arenas grouped for the Bounty screen.
 * @returns {{ id: string, name: string, desc: string, mapId: string, stages: string[] }[]}
 */
export function bountyArenas() {
  return BOUNTY_DEFS.map((d) => ({ id: d.id, name: d.name, desc: d.desc, mapId: d.mapId, stages: [1, 2, 3].map((t) => `${d.id}-${t}`) }));
}

/**
 * Every enemy id that can appear in a stage, including split/brood/summon/decoy children.
 * @param {object|string} stageOrId StageDef or id
 * @param {(id: string) => object|undefined} [lookupEnemy] enemy lookup (defaults to the real bestiary)
 * @returns {string[]}
 */
export function stageEnemies(stageOrId, lookupEnemy = (id) => ENEMY_MAP[id]) {
  const stage = typeof stageOrId === 'string' ? getStage(stageOrId) : stageOrId;
  const out = new Set();
  const visit = (id, depth) => {
    if (out.has(id) || depth > 4) return;
    out.add(id);
    const def = lookupEnemy(id);
    if (!def) return;
    const sets = [def.traits || {}, ...(def.phases || []).map((ph) => ph.set?.traits || {})];
    for (const t of sets) for (const k of ['brood', 'splitter', 'summoner', 'decoy']) if (t[k]?.spawn) visit(t[k].spawn, depth + 1);
  };
  for (const p of stage.waveGen.pool) visit(p.enemy, 0);
  for (const f of stage.waveGen.fixed) visit(f.enemy, 0);
  return [...out];
}

/**
 * Campaign stage ids: Act I in play order (1-1 … 8-5), then the registered Act II stages by (chapter, n). Act I comes
 * first so "the first uncleared stage" (src/systems/unlocks.js nextStage) never pulls a veteran back to 1-6; lists
 * that mean play order sort by stageOrderKey instead of this array's index.
 */
export const CAMPAIGN_IDS = [...CAMPAIGN_ORDER, ...ACT2_SORTED.map((s) => s.id)];

/** Campaign ids per act, in play order: { 1: ['1-1', …, '8-5'], 2: [registered Act II ids] }. */
const ACT_IDS = Object.freeze({
  1: Object.freeze(CAMPAIGN_ORDER.slice()),
  2: Object.freeze(ACT2_SORTED.map((s) => s.id)),
});

// ---------------------------------------------------------------------------
// Requirements and play order (the only readers of StageDef.requires and of a stage's act)
// ---------------------------------------------------------------------------

/**
 * The stage ids that must be cleared before a stage opens: none, one, or (an Act II x-6) two. This is the only
 * reader of `StageDef.requires`, which is a stage id, a list of stage ids, or null.
 * @param {object|string|null|undefined} stageOrId StageDef or stage id
 * @returns {string[]}
 */
export function stageRequires(stageOrId) {
  const stage = typeof stageOrId === 'string' ? STAGE_MAP[stageOrId] : stageOrId;
  const r = stage?.requires;
  if (!r) return [];
  return (Array.isArray(r) ? r : [r]).filter((id) => typeof id === 'string' && id.length > 0);
}

/**
 * Every requirement of the stage is cleared (true when it has none). The unlock rule of the campaign, Bounty and
 * Total Assault: src/systems/unlocks.js isStageUnlocked and src/systems/story.js stageOpen both read it.
 * @param {object|string|null|undefined} stageOrId StageDef or stage id
 * @param {(stageId: string) => boolean} isCleared cleared on any difficulty
 * @returns {boolean}
 */
export function requirementsMet(stageOrId, isCleared) {
  return stageRequires(stageOrId).every((id) => !!isCleared(id));
}

const CAMPAIGN_ID_RE = /^(\d+)-(\d+)$/;

/**
 * A campaign stage id's play-order key: (chapter, act, n) as one number, so 1-10 comes before 2-1 and 1-5 before 1-6.
 * Works for ids not registered yet (the act then comes from n: 1…5 Act I, 6…10 Act II, 11…15 Act III, reserved).
 * Any other id (Bounty, Total Assault, events, unknown) sorts last: Infinity.
 * @param {string} id
 * @returns {number}
 */
export function stageOrderKey(id) {
  const m = CAMPAIGN_ID_RE.exec(typeof id === 'string' ? id : '');
  if (!m) return Infinity;
  const chapter = Number(m[1]);
  const n = Number(m[2]);
  const act = STAGE_MAP[id]?.act ?? Math.ceil(n / 5);
  return chapter * 10000 + act * 100 + n;
}

/**
 * The registered stage ids of one act of a chapter (act 1: `chapter.stages`; act 2: `chapter.act2`).
 * @param {number|string} chapterId
 * @param {number|string} [act]
 * @returns {string[]}
 */
export function actStages(chapterId, act = 1) {
  const ch = CHAPTERS.find((c) => c.id === Number(chapterId));
  if (!ch) return [];
  const a = Number(act);
  return a === 1 ? ch.stages : a === 2 ? ch.act2 : [];
}

/**
 * The campaign stage after `id` in the same act: Act I runs 1-1 … 8-5 (8-5 → null, never 1-6); Act II runs 1-6 … 8-10
 * over the registered stages (x-10 → (c+1)-6 when it exists). Null for the last stage of an act and for every other id.
 * @param {string} id
 * @returns {string|null}
 */
export function nextInAct(id) {
  const s = STAGE_MAP[id];
  if (!s || s.kind !== 'campaign') return null;
  const list = ACT_IDS[s.act] || [];
  const i = list.indexOf(id);
  return i >= 0 && i < list.length - 1 ? list[i + 1] : null;
}
